```powershell
# if/elseif/else
if ($x -gt 0) {
    Write-Host "positive"
} elseif ($x -eq 0) {
    Write-Host "zero"
} else {
    Write-Host "negative"
}

# Comparison operators (NO < > == in PowerShell!)
-eq  -ne  -lt  -gt  -le  -ge    # equal, not-equal, less, greater...
-like     # wildcard: "hello" -like "h*"
-match    # regex: "hello" -match "h\w+" → $Matches
-contains # array: @(1,2,3) -contains 2
-in       # 2 -in @(1,2,3)
-and  -or  -not  -xor

# switch (powerful!)
switch ($day) {
    "Monday"   { "Start of week" }
    "Friday"   { "End of week" }
    { $_ -match "^S" } { "Weekend" }  # regex!
    default    { "Midweek" }
}

# Loops
foreach ($item in $collection) { Write-Host $item }
1..10 | ForEach-Object { $_ * 2 }  # pipeline

for ($i = 0; $i -lt 10; $i++) { Write-Host $i }

$n = 0
while ($n -lt 10) { $n++ }
do { $n++ } while ($n -lt 20)

# break / continue
foreach ($i in 1..10) {
    if ($i -eq 5) { break }
    if ($i % 2 -eq 0) { continue }
    Write-Host $i
}
```

```powershell
# Basic function
function Get-Greeting {
    param(
        [string]$Name = "World",
        [int]$Times = 1
    )
    1..$Times | ForEach-Object { "Hello, $Name!" }
}
Get-Greeting -Name "Alice" -Times 3

# Advanced function with CmdletBinding
function Invoke-Process {
    [CmdletBinding(SupportsShouldProcess)]
    param(
        [Parameter(Mandatory, ValueFromPipeline)]
        [string]$Path,

        [Parameter()]
        [switch]$Force,

        [ValidateSet("Info","Warning","Error")]
        [string]$Level = "Info"
    )

    begin { Write-Verbose "Starting" }
    process {
        if ($PSCmdlet.ShouldProcess($Path, "Process")) {
            Write-Verbose "Processing: $Path"
        }
    }
    end { Write-Verbose "Done" }
}

# Pipeline function
function Add-One {
    process { $_ + 1 }  # $_ is current pipeline item
}
1, 2, 3 | Add-One   # 2 3 4

# Script block
$sq = { param($x) $x * $x }
& $sq 5   # invoke: 25
```

```powershell
# Try/Catch/Finally
try {
    Get-Item "nonexistent.txt" -ErrorAction Stop
} catch [System.IO.FileNotFoundException] {
    Write-Host "File not found: $_"
} catch {
    Write-Host "Error: $($_.Exception.Message)"
    Write-Host "Type: $($_.Exception.GetType().Name)"
} finally {
    Write-Host "Cleanup"
}

# ErrorAction preference
$ErrorActionPreference = "Stop"         # stop on all errors
Get-Item "file.txt" -ErrorAction Stop              # throws
Get-Item "file.txt" -ErrorAction SilentlyContinue  # ignores

# Throw
throw "Custom error message"
throw [System.ArgumentException]::new("Invalid argument")

# Background jobs
$job = Start-Job { Get-Process }
Get-Job
Wait-Job $job
Receive-Job $job -AutoRemoveJob

# Parallel processing (PowerShell 7+)
1..10 | ForEach-Object -Parallel {
    Start-Sleep 1
    "Done: $_"
} -ThrottleLimit 5

# Remoting
Invoke-Command -ComputerName Server01 { Get-Service }
$session = New-PSSession -ComputerName Server01
Invoke-Command -Session $session { Get-Process }
Remove-PSSession $session
